/* Derive the menu/completion total from all authored entries. The existing
 * cartridge record reserves seven bytes, so future additions cannot silently
 * truncate missions or overwrite the next SRAM record. */
enum { NMIS = sizeof(MIS) / sizeof(MIS[0]), MISSION_SAVE_BYTES = 7 };
typedef char mission_catalog_fits_save[(NMIS <= MISSION_SAVE_BYTES * 8) ? 1 : -1];

/* record points to the existing 'M', 'I', then seven completion bytes. */
static inline uint8_t mission_progress_done(const volatile uint8_t *record, uint8_t i) {
  if (i >= NMIS || record[0] != 'M' || record[1] != 'I') return 0;
  return (uint8_t)((record[2 + i / 8] >> (i & 7)) & 1);
}
static inline uint8_t mission_progress_count(const volatile uint8_t *record) {
  uint8_t i, n = 0;
  for (i = 0; i < NMIS; i++) n += mission_progress_done(record, i);
  return n;
}
static inline void mission_progress_mark(volatile uint8_t *record, uint8_t i) {
  uint8_t k;
  if (i >= NMIS) return;
  if (record[0] != 'M' || record[1] != 'I') {
    for (k = 0; k < MISSION_SAVE_BYTES; k++) record[2 + k] = 0;
    record[0] = 'M'; record[1] = 'I';
  }
  record[2 + i / 8] |= (uint8_t)(1u << (i & 7));
}
